arguments.content:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\nkaede\t2026-01-05\t13:00\t14:00\tz\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# 同じ日付・同じ開始の別の部屋の予約は残る
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "other room's booking removed"; fail=1; }
# ヘッダ行と他の予約は変わらない
[ "$(head -1 "$t")" = "$(printf '# room\tdate\tstart\tend\twho')" ] || { echo "header changed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking removed"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
# not found は stdout に何も出さず、メッセージは stderr
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$o" ] || { echo "not found wrote stdout: $o"; fail=1; }
# 引数の数が違うときは exit 2、usage は stderr
o=$(bash src/cancel.sh aoi 2>/dev/null); c=$?; [ "$c" = 2 ] && [ -z "$o" ] || { echo "usage: exit $c, stdout: $o"; fail=1; }
rm -f "$t"; exit $fail

